//! `effective_role` against crates/core/tests/roles.csv (generated by
//! scripts/gen_authz_matrix.py from the documented rules): every
//! combination of collaborator, team, organization, namespace ownership,
//! site administration, and the organization MFA requirement.
#![allow(clippy::unwrap_used, clippy::expect_used)]

use slath_core::authz::{Role, RoleGrants, effective_role};

fn role(s: &str) -> Option<Role> {
    (s != "none").then(|| s.parse().unwrap())
}

#[test]
fn effective_role_matches_the_table() {
    let csv = include_str!("roles.csv");
    let mut rows = 0;
    for line in csv.lines().filter(|l| !l.starts_with('#')).skip(1) {
        let f: Vec<&str> = line.split(',').collect();
        let [collab, team, org, ns, admin, mfa, expect] = f[..] else {
            panic!("bad row {line}");
        };
        let g = RoleGrants {
            site_admin: admin == "true",
            namespace_owner: ns == "true",
            collaborator: role(collab),
            // Several teams: the extra read team must never lower the result.
            teams: role(team)
                .into_iter()
                .chain([Role::Read].into_iter().filter(|_| team != "none"))
                .collect(),
            org_owner: org == "owner",
            org_member: org != "none",
            org_default_member_role: (org == "member-default-read").then_some(Role::Read),
            org_mfa_unmet: mfa == "true",
        };
        assert_eq!(effective_role(&g), role(expect), "{line}");
        rows += 1;
    }
    assert_eq!(rows, 800);
}
